import { NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { COPY } from "@/copy";

/**
 * The letter's way out.
 *
 * Every letter carries a per-subscriber link here (and the same URL in its List-Unsubscribe
 * header, with List-Unsubscribe-Post for one-click). The token is `unsub_token` on the row the
 * subscribe route wrote; nothing else identifies the reader.
 *
 * A GET NEVER WRITES. Corporate mail security (Safe Links, URL Defense) prefetches every URL in
 * an inbound message, so a route that unsubscribed on GET would remove a reader on DELIVERY of
 * the first letter they were ever sent. GET renders a button; only the POST writes. RFC 8058
 * one-click lives on POST too, which scanners do not issue.
 */

const TOKEN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const PUBLICATION = COPY.handle.replace(/^@/, "");

function page(heading: string, body: string, status = 200): Response {
  const site = COPY.site.replace(/\/$/, "");
  const style = `
    :root{color-scheme:light}
    body{margin:0;background:#f6f3ec;font-family:Georgia,'Times New Roman',serif;color:#2b2722}
    .wrap{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px}
    .card{background:#fff;max-width:460px;width:100%;padding:40px}
    h1{font-size:22px;line-height:1.2;margin:0 0 12px;font-weight:400}
    p{font-size:16px;line-height:1.6;margin:0 0 14px}
    .foot{font-size:13px;color:#7a736a;margin:22px 0 0}
    button{font:inherit;font-size:15px;background:#2b2722;color:#fff;border:0;border-radius:6px;padding:12px 20px;cursor:pointer}
    a{color:#2b2722}
  `;
  return new Response(
    `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>${COPY.name}</title><style>${style}</style></head><body><div class="wrap"><div class="card"><h1>${heading}</h1>${body}<p class="foot">${COPY.name} · <a href="${site}">${site.replace(/^https?:\/\//, "")}</a></p></div></div></body></html>`,
    { status, headers: { "content-type": "text/html; charset=utf-8", "x-robots-tag": "noindex, nofollow" } },
  );
}

function token(req: Request): string | null {
  const t = new URL(req.url).searchParams.get("token");
  return t && TOKEN.test(t) ? t : null;
}

const BAD = `<p>That link could not be read. It may have been cut short by your mail client.</p><p>Reply to any letter with the word unsubscribe and it will be done by hand.</p>`;

export async function GET(req: Request) {
  const t = token(req);
  if (!t) return page("That link didn't work", BAD, 400);
  const action = `/api/subscribe/unsubscribe?token=${encodeURIComponent(t)}`;
  return page(
    "One more click",
    `<p>Confirm you'd like to stop receiving the letter from ${COPY.name}.</p>` +
      `<form method="POST" action="${action}"><button type="submit">Unsubscribe me</button></form>` +
      `<p class="foot">We ask because mail scanners follow links in email, and we would rather not remove you by accident.</p>`,
  );
}

export async function POST(req: Request) {
  const t = token(req);
  const wantsHtml = (req.headers.get("accept") || "").includes("text/html");
  const url = process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!t || !url || !key) {
    return wantsHtml ? page("That link didn't work", BAD, 400) : new NextResponse(null, { status: 400 });
  }
  const sb = createClient(url, key, { auth: { persistSession: false } });
  const { data, error } = await sb
    .from("publication_subscribers")
    .update({ unsubscribed: true })
    .eq("publication", PUBLICATION)
    .eq("unsub_token", t)
    .select("email")
    .maybeSingle();
  if (error) {
    return wantsHtml
      ? page("That didn't work", "<p>Something went wrong on our side. Try the link again in a moment.</p>", 500)
      : new NextResponse(null, { status: 500 });
  }
  if (!wantsHtml) return new NextResponse(null, { status: 200 });
  return data
    ? page("You're off the list", `<p>Done. No more letters. If that was a mistake, the form on the site takes you back in one field.</p>`)
    : page("That link didn't work", BAD, 400);
}

